// Loads the sprite sheets (PNG + JSON description, generated by tools/art) and checks them.
import * as THREE from 'three';
import { REQUIRED_SHEETS } from '../data/assets.js';

const metas = import.meta.glob('../../assets/sheets/*.json', { eager: true, import: 'default' });
const urls = import.meta.glob('../../assets/sheets/*.png', { eager: true, query: '?url', import: 'default' });

/** name -> { meta, url, image, texture } */
export const sheets = {};

function loadImage(url) {
  return new Promise((resolve, reject) => {
    const image = new Image();
    image.onload = () => resolve(image);
    image.onerror = () => reject(new Error(`Не удалось загрузить изображение ${url}`));
    image.src = url;
  });
}

/** Loads everything and throws one readable error listing all missing sheets and animations. */
export async function loadAssets() {
  const byName = (map) => Object.fromEntries(Object.entries(map).map(([path, v]) => [path.split('/').pop().split('.')[0], v]));
  const metaByName = byName(metas);
  const urlByName = byName(urls);
  const problems = [];

  await Promise.all(
    Object.entries(metaByName).map(async ([name, meta]) => {
      if (!urlByName[name]) {
        problems.push(`нет картинки для листа "${name}"`);
        return;
      }
      const image = await loadImage(urlByName[name]);
      const texture = new THREE.Texture(image);
      // Pixel art: no smoothing, no mipmaps, colours passed through untouched.
      texture.magFilter = THREE.NearestFilter;
      texture.minFilter = THREE.NearestFilter;
      texture.generateMipmaps = false;
      texture.colorSpace = THREE.NoColorSpace;
      texture.needsUpdate = true;
      // How many game pixels one pixel of the sheet covers (see tools/art/lib.mjs).
      meta.scale ??= 1;
      sheets[name] = { meta, url: urlByName[name], image, texture };
    }),
  );

  for (const [name, anims] of Object.entries(REQUIRED_SHEETS)) {
    if (!sheets[name]) {
      problems.push(`нет листа спрайтов "${name}"`);
      continue;
    }
    for (const anim of anims) if (!sheets[name].meta.anims[anim]) problems.push(`в листе "${name}" нет анимации "${anim}"`);
  }
  if (problems.length) throw new Error(`Проблемы с графикой:\n- ${problems.join('\n- ')}`);
}

export function animOf(sheet, anim) {
  const entry = sheets[sheet]?.meta.anims[anim];
  if (!entry) throw new Error(`Нет анимации "${anim}" в листе "${sheet}"`);
  return entry;
}

/**
 * Inline CSS that shows one frame of a sheet in a DOM element, scaled by the --px variable
 * (the size of one game pixel on screen) so interface icons stay pixel-perfect.
 */
export function iconCss(sheet, anim, frame = 0) {
  const { meta, url } = sheets[sheet];
  const entry = animOf(sheet, anim);
  const px = (n) => `calc(${n} * var(--px))`;
  return [
    `width:${px(meta.cellW)}`,
    `height:${px(meta.cellH)}`,
    `background-image:url("${url}")`,
    `background-size:${px(meta.width)} ${px(meta.height)}`,
    `background-position:${px(-frame * meta.cellW)} ${px(-entry.row * meta.cellH)}`,
  ].join(';');
}

/** A small DOM element showing a sprite frame. */
export function icon(sheet, anim, frame = 0) {
  const el = document.createElement('i');
  el.className = 'icon';
  el.style.cssText = iconCss(sheet, anim, frame);
  return el;
}
